## Port of `rich.emoji` (rich/emoji.py).
##
## `Emoji` (emoji.py:20-72): a single emoji character renderable
## (`class Emoji(JupyterMixin)`); `replace` (emoji.py:51-57) swaps `:name:`
## markup for the character; `EmojiVariant = Literal["emoji", "text"]`
## (emoji.py:13) selects VS-16/VS-15 presentation; `NoEmoji` (emoji.py:16) is
## raised for unknown names.
##
## rich/emoji.py imports (emoji.py:1-7): `from .jupyter import JupyterMixin`
## (emoji.py:5), `from .segment import Segment` (emoji.py:6), `from .style
## import Style` (emoji.py:7); `from .console import …` (emoji.py:10) is
## TYPE_CHECKING-only. `_emoji_replace` (emoji.py:4) and `EMOJI` (emoji.py:31)
## are body-only → not imported .
##
## wiring (this file) — imports only siblings within the port
## 10-module set + std:
##   `import std/[options, tables]` — `Option[EmojiVariant]` (the `variant:
##                       Optional[EmojiVariant] = None` param, emoji.py:26);
##                       `Table[string, string]` (`VARIANTS`, emoji.py:24).
##   `import richbase`   — `JupyterMixin` (the field-less Python base, `class
##                       Emoji(JupyterMixin)`, emoji.py:20 — cycle-breaker
##                       declared in `richbase`); `RenderResult`,
##                       `ConsoleOptions`, `ConsoleHandle` (the
##                       `__rich_console__` signature, emoji.py:65).
##   `import style`      — `Style`, `StyleType` (`style: Union[str, Style] =
##                       "none"`, emoji.py:25; `StyleType = Union[str, Style]`,
##                       style.py:19); `StyleValue` (the storable
##                       `Union[str, Style]` handle for the `Emoji.style`
##                       field, emoji.py:33 — moved to `style.nim` from
##                       `text.nim` for the 10-module closure). This
##                       file defines the real `EmojiVariant` (emoji.py:13).
##
## `EmojiVariant` → string-valued enum (`$` yields the exact Python token).
## `_char` (the `__slots__` slot) → `` `char` `` (backtick-quoted; `char` is a
## Nim keyword). `replace` classmethod (emoji.py:51) → `proc replace*(T:
## typedesc[Emoji], …)`. `__str__`→`str`, `__repr__`→`repr`,
## `__rich_console__`→`renderConsole`. Bodies mirror the Python source (`discard`).

import std/[options, tables, unicode]   # Option[EmojiVariant] (emoji.py:26);
                               # Table[string, string] (VARIANTS, emoji.py:24).

import richbase    # JupyterMixin (emoji.py:20, cycle-breaker in richbase);
                   # RenderResult, ConsoleOptions, ConsoleHandle (emoji.py:65).
import style       # Style, StyleType (emoji.py:25; style.py:19); StyleValue
                   # (Union[str, Style] field handle, emoji.py:33 — from style).

type
  EmojiVariant* = enum
    ## rich emoji.py:13 — `EmojiVariant = Literal["emoji", "text"]`: the
    ## emoji/text presentation selector (VS-16 `\ufe0f` / VS-15 `\ufe0e`).
    evEmoji = "emoji"  ## the `"emoji"` literal (emoji.py:13) — VS-16 `\ufe0f`.
    evText = "text"    ## the `"text"`  literal (emoji.py:13) — VS-15 `\ufe0e`.

  NoEmoji* = object of CatchableError
    ## rich emoji.py:16-17 — `class NoEmoji(Exception)`: "No emoji by that
    ## name." Raised by `Emoji.__init__` on `EMOJI[name]` miss (emoji.py:33-34).

  Emoji* = ref object of JupyterMixin
    ## rich emoji.py:20-48 — `class Emoji(JupyterMixin)`: a single emoji
    ## character renderable. `__slots__ = ["name", "style", "_char", "variant"]`
    ## (emoji.py:21); fields mirror `__init__` (emoji.py:32-37).
    name*: string                   ## rich emoji.py:32 — `self.name = name` (`str`).
    style*: StyleValue              ## rich emoji.py:33 — `self.style = style` (`Union[str, Style]`).
    `char`*: string                 ## rich emoji.py:34 — `self._char = EMOJI[name]` (backtick-quoted; `char` is a Nim keyword).
    variant*: Option[EmojiVariant]  ## rich emoji.py:35 — `self.variant = variant` (`Optional[EmojiVariant]`).

let
  emojiVariants* {.used.} = {"text": "\uFE0E", "emoji": "\uFE0F"}.toTable
    ## rich emoji.py:24 — `VARIANTS = {"text": "\ufe0e", "emoji": "\ufe0f"}`:
    ## class-level presentation-selector table. `let` + ``; the 2 VS
    ## entries are wired here (body). Public (class attr).

## ── `rich._emoji_codes.EMOJI` + `rich._emoji_replace._emoji_replace` ──────
## The complete 3608-entry alias→unicode table (Rich 15.0.0), plus a faithful
## manual port of `_emoji_replace(text, default_variant=None)` (emoji.py:4 →
## `_emoji_replace.py`). The Python regex
## `(:(\S*?)(?:(?:\-)(emoji|text))?:)` is ported as a manual scan (the host has
## no `libpcre` runtime, so `std/re` is avoided, matching `markup.nim`). `\S`
## matches Python 3 `re` `\s` (UNICODE) for `str` — the authoritative set is
## `0x09 0x0a 0x0b 0x0c 0x0d 0x1c 0x1d 0x1e 0x1f 0x20 0x85 0xa0 0x1680
## 0x2000..0x200a 0x2028 0x2029 0x202f 0x205f 0x3000`. The non-greedy `\S*?`
## with the greedy-optional `(-emoji|-text)?` is replicated by scanning the
## candidate closing-colon position ascending (rune-aligned) and, per position,
## trying the `emoji`/`text` variant arms before the no-variant arm — exactly
## Python's leftmost-shortest match with optional-group backtracking. Lookup
## lowercases the captured name with Unicode `toLower` (matches `str.lower()`
## for the Latin-accented + curly-apostrophe EMOJI keys); an unknown alias
## yields the original `:…:` unchanged (KeyError → `emoji_code`, emoji.py:24).
## `defaultVariant` carries the Console's `emoji_variant` (None ⇒ no
## presentation-suffix, like a default `Console()`).
