  "regional_indicator_w": "\xF0\x9F\x87\xBC",
  "regional_indicator_x": "\xF0\x9F\x87\xBD",
  "regional_indicator_y": "\xF0\x9F\x87\xBE",
  "regional_indicator_z": "\xF0\x9F\x87\xBF",
}.toTable

proc isPythonWs(r: Rune): bool =
  ## rich `_emoji_replace` regex `\S` boundary — the set of codepoints Python 3
  ## `re` `\s` (UNICODE) matches for a `str` subject (enumerated from the
  ## authoritative Rich 15.0.0 installation). Whitespace inside `:name:` breaks
  ## the non-ws run, so an alias cannot span it — matching Python exactly.
  let c = r.ord
  case c
  of 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85, 0xa0,
     0x1680, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000:
    true
  of 0x2000..0x200a:
    true
  else:
    false

proc emojiSliceEq(s: string, pos: int, needle: string): bool =
  ## Byte-exact substring test at `pos` (no slicing → no bounds raise). Used to
  ## match the `-emoji`/`-text` variant suffixes.
  if pos + needle.len > s.len: return false
  var i = 0
  while i < needle.len:
    if s[pos + i] != needle[i]: return false
    inc i
  return true

proc toLowerUni(s: string): string =
  ## Unicode lowercasing (matches Python `str.lower()` for the EMOJI keys —
  ## Latin-accented letters and the curly apostrophe all lower-case 1:1).
  result = newStringOfCap(s.len)
  for ru in s.toRunes:
    result.add($toLower(ru))

proc emojiReplace*(text: string,
                   defaultVariant: Option[EmojiVariant] = none(EmojiVariant)): string =
  ## rich `_emoji_replace._emoji_replace(text, default_variant=None)` (the
  ## helper bound by `Emoji.replace` and called by `markup.render` /
  ## `Console.render_str`). Replaces `:name[-variant]:` markup with the
  ## `EMOJI[name.lower()]` unicode char plus the presentation suffix:
  ##   • `:smiley:`        → `EMOJI["smiley"]` (+ `defaultVariant` suffix)
  ##   • `:smiley-emoji:`  → `EMOJI["smiley"]` + `\uFE0F` (VS-16)
  ##   • `:smiley-text:`   → `EMOJI["smiley"]` + `\uFE0E` (VS-15)
  ##   • `:unknown:`       → `:unknown:` unchanged (KeyError → original match).
  const
    suffixEmoji = "-emoji"   ## 6 bytes — the `-emoji` variant suffix.
    suffixText = "-text"     ## 5 bytes — the `-text`  variant suffix.
    varEmoji = "\uFE0F"      ## VS-16 presentation selector (`emoji`).
    varText = "\uFE0E"      ## VS-15 presentation selector (`text`).
  var defaultCode = ""
  if defaultVariant.isSome:
    case defaultVariant.get
    of evEmoji: defaultCode = varEmoji
    of evText: defaultCode = varText
  result = newStringOfCap(text.len)
  let n = text.len
  var i = 0
  while i < n:
    if text[i] != ':':
      # copy one rune (multi-byte emoji chars must not be split byte-wise)
      let w = text.runeLenAt(i)
      if w <= 0: result.add(text[i]); inc i; continue
      result.add(text[i ..< i + w])
      i += w
      continue
    # opening ':' at byte i. Determine the non-ws run from i+1 (the regex's
    # `\S*?` content + optional variant + closing ':' all live inside it).
    var pos = i + 1
    while pos < n:
      let r = text.runeAt(pos)
      if isPythonWs(r): break
      pos += text.runeLenAt(pos)
    let runEnd = pos
    # Scan candidate closing positions ascending (rune-aligned). Per position
    # try variant-emoji, variant-text, then no-variant — the arms are mutually
    # exclusive at a given `pos` (`-` vs `:`), so the first that fires is the
    # leftmost-shortest match, exactly Python's non-greedy `\S*?` with the
    # greedy-optional `(-emoji|-text)?`.
    pos = i + 1
    var matched = false
    var matchEnd = 0
    var matchName = ""
    var matchVar: Option[EmojiVariant] = none(EmojiVariant)
    while pos < runEnd:
      if text[pos] == '-' and emojiSliceEq(text, pos, suffixEmoji):
        if pos + 6 < n and text[pos + 6] == ':':
          matchName = text[i + 1 ..< pos]
          matchVar = some(evEmoji)
          matchEnd = pos + 6
          matched = true
          break
      if text[pos] == '-' and emojiSliceEq(text, pos, suffixText):
        if pos + 5 < n and text[pos + 5] == ':':
          matchName = text[i + 1 ..< pos]
          matchVar = some(evText)
          matchEnd = pos + 5
          matched = true
          break
      if text[pos] == ':':
        matchName = text[i + 1 ..< pos]
        matchVar = none(EmojiVariant)
        matchEnd = pos
        matched = true
        break
      let w = text.runeLenAt(pos)
      if w <= 0: inc pos else: pos += w
    if matched:
      let key = matchName.toLowerUni()
      if emojiCodes.hasKey(key):
        result.add(emojiCodes[key])
        if matchVar.isSome:
          case matchVar.get
          of evEmoji: result.add(varEmoji)
          of evText: result.add(varText)
        else:
          result.add(defaultCode)
        i = matchEnd + 1
      else:
        # unknown alias: emit the original `:…:` unchanged (KeyError path).
        result.add(text[i .. matchEnd])
        i = matchEnd + 1
    else:
      result.add(':')
      inc i

proc initEmoji*(name: string, style: StyleType = "none",
                variant: Option[EmojiVariant] = none(EmojiVariant)): Emoji =
  ## rich emoji.py:25-37 — `Emoji.__init__(self, name: str, style: Union[str,
  ## Style] = "none", variant: Optional[EmojiVariant] = None) -> None`. Faithful:
  ## `EMOJI[name]` (emoji.py:34, direct lookup — NOT lowercased; only
  ## `_emoji_replace` lowercases the regex capture) raises `NoEmoji` on a miss,
  ## then `VARIANTS.get(variant, "")` appends the presentation selector
  ## (emoji.py:35).
  result = Emoji()
  result.name = name
  result.style = style
  result.variant = variant
  if emojiCodes.hasKey(name):
    result.char = emojiCodes[name]
  else:
    raise newException(NoEmoji, "No emoji called '" & name & "'")
  if variant.isSome:
    result.char &= emojiVariants.getOrDefault($variant.get, "")

proc replace*(T: typedesc[Emoji], text: string): string =
  ## rich emoji.py:51-57 — `Emoji.replace(cls, text: str) -> str` (classmethod):
  ## replace `:name:` markup with the unicode character (delegates to
  ## `_emoji_replace`, emoji.py:56). Faithful: delegates to the ported
  ## `emojiReplace` (= `_emoji_replace`, default_variant=None, emoji.py:56).
  result = emojiReplace(text)

proc repr*(self: Emoji): string =
  ## rich emoji.py:59-60 — `Emoji.__repr__(self) -> str`:
  ## `f"<emoji {self.name!r}>"`. Overloads `system.repr` on the `Emoji`
  ## receiver. Faithful: `f"<emoji {self.name!r}>"` (single-quoted `!r`).
  result = "<emoji '" & self.name & "'>"

proc str*(self: Emoji): string =
  ## rich emoji.py:62-63 — `Emoji.__str__(self) -> str`: `return self._char`.
  ## Faithful.
  result = self.char

method renderConsole*(self: Emoji, console: ConsoleHandle,
                    options: ConsoleOptions): RenderResult =
  ## rich emoji.py:65-71 — `Emoji.__rich_console__(self, console: "Console",
  ## options: "ConsoleOptions") -> RenderResult`: `yield Segment(self._char,
  ## console.get_style(self.style))` (emoji.py:71).
  result = @[]
  # `console.get_style(self.style)` (emoji.py:71) — the `Console` is the opaque
  # `ConsoleHandle` placeholder, so resolve the `StyleValue` style locally
  # (str → `Style.parse`, error → `Style.null()`, Style → `.copy()`), the
  # documented approximation of `console.get_style` (theme names miss → null).
  # `Segment.style: Option[StyleRef]`; `Style` is a ref object of `StyleRef`,
  # upcast via `StyleRef(style)`.
  var style: Style
  case self.style.kind
  of svkStr:
    try: style = Style.parse(self.style.strv)
    except CatchableError: style = Style.null()
  of svkStyle:
    style = self.style.stv.copy()
  result.addSegment(initSegment(self.char, some(StyleRef(style))))
